// Vendored stand-in for `lodash`'s `debounce`, following the project policy of
// shipping third-party code in-repo instead of `npm install` (this environment
// has no network, so the upstream package could not be fetched). This is NOT
// upstream lodash code; it implements lodash's debounce API and semantics for
// the options used here (leading, trailing, cancel, flush). `maxWait` is not
// supported. When a network-enabled checkout can run `npm i lodash`, replace
// this file with the upstream `lodash/debounce.js` (MIT licensed).

export default function debounce(func, wait = 0, options = {}) {
  if (typeof func !== 'function') {
    throw new TypeError('Expected a function');
  }
  const leading = options.leading === true;
  const trailing = options.trailing !== false;
  wait = Math.max(0, Number(wait) || 0);

  let timerId;
  let lastArgs;
  let lastThis;
  let result;

  function invoke() {
    const args = lastArgs;
    const thisArg = lastThis;
    lastArgs = lastThis = undefined;
    result = func.apply(thisArg, args);
    return result;
  }

  function onTimedOut() {
    timerId = undefined;
    if (trailing && lastArgs) return invoke();
    lastArgs = lastThis = undefined;
    return result;
  }

  function debounced(...args) {
    const isFirstCallOfBurst = timerId === undefined;
    lastArgs = args;
    lastThis = this;
    if (isFirstCallOfBurst && leading) invoke();
    clearTimeout(timerId);
    timerId = setTimeout(onTimedOut, wait);
    return result;
  }

  debounced.cancel = function cancel() {
    clearTimeout(timerId);
    timerId = undefined;
    lastArgs = lastThis = undefined;
  };

  debounced.flush = function flush() {
    if (timerId === undefined) return result;
    clearTimeout(timerId);
    timerId = undefined;
    if (lastArgs) return invoke();
    return result;
  };

  return debounced;
}

